    let timedOut = false;
    const timer = setTimeout(() => {
        timedOut = true;
        controller.abort(new TimeoutError(timeoutMs));
    }, timeoutMs);
    const done = () => {
        clearTimeout(timer);
        callerSignal?.removeEventListener('abort', onCallerAbort);
    };
    const failure = (e: unknown) => (timedOut ? new TimeoutError(timeoutMs, e instanceof Error ? e : undefined) : e);

    let response: Response;
    try {
        // Raced against the abort, so a fetchApi that ignores the signal and never answers is still
        // bounded by timeoutMs and the caller's signal.
        // Promise.resolve: a fetchApi stub may return a plain Response rather than a promise.
        const answer = Promise.resolve(fetchApi(url, { ...init, signal: controller.signal }));
        const aborted = new Promise<never>((_, reject) => {
            const onAbort = () => reject(controller.signal.reason);
            if (controller.signal.aborted) onAbort();
            else controller.signal.addEventListener('abort', onAbort, { once: true });
        });
        answer.catch(() => undefined);
        aborted.catch(() => undefined);
        response = await Promise.race([answer, aborted]);
    } catch (e) {
        done();
        throw failure(e);
    }
    try {
        return wrapBody(response, controller.signal, done, failure);
    } catch (e) {
        done();
        throw failure(e);
    }
